# -*- coding: utf-8 -*- # Языковая кодировка UTF-8
import json
from collections import Counter

from colorama import Fore, Style
from rich.console import Console
from rich.table import Table

from tools.core.data.pronouns import (pers_possessive_pronouns_analysis_list,
                                      reflexive_pronoun_list,
                                      demonstrative_pronouns_list,
                                      defining_pronouns_list,
                                      relative_pronouns_list,
                                      indefinite_pronouns_list,
                                      negative_pronouns_list
                                      )
from tools.core.utils import wait_for_enter_to_analyze
from tools.core.lemmatizators import lemmatize_words

console = Console()


def compute_pronoun_frequencies(text, pronouns_list, show_analysis=True):
    """
    Вычисляет абсолютные и нормализованные частоты местоимений в тексте.

    :param text: Входной текст на русском языке.
    :param show_analysis: Определяет, выводить ли анализ в терминал.

    :return: JSON-строка с нормализованными частотами местоимений и JSON-строка сабсолютными частотами.
    """
    tokens_info = lemmatize_words(text)
    token_counts = Counter()
    pronoun_frequencies = {}

    # Подсчёт частот всех токенов
    for token in tokens_info:
        token_counts[token.normal_form] += 1

    # Подсчёт частот только местоимений
    pronoun_counts = {pronoun: token_counts[pronoun] for pronoun in pronouns_list if pronoun in token_counts}

    total_tokens_count = sum(token_counts.values())

    if total_tokens_count > 0:
        pronoun_frequencies = {k: (v / total_tokens_count) * 100 for k, v in pronoun_counts.items()}

    # Сортировка по частоте
    sorted_pronoun_frequencies = sorted(pronoun_frequencies.items(), key=lambda item: item[1], reverse=True)
    rounded_pronoun_frequencies = {pronoun: round(frequency, 3) for pronoun, frequency in sorted_pronoun_frequencies}

    sorted_pronoun_counts = sorted(pronoun_counts.items(), key=lambda item: item[1], reverse=True)

    pronoun_freqs_json = json.dumps(rounded_pronoun_frequencies, ensure_ascii=False)
    pronoun_counts_json = json.dumps(dict(sorted_pronoun_counts), ensure_ascii=False)
    pronouns_type = ''
    if pronouns_list == pers_possessive_pronouns_analysis_list:
        pronouns_type = 'pers_possessive'
    elif pronouns_list == reflexive_pronoun_list:
        pronouns_type = 'reflexive_pronoun'
    elif pronouns_list == demonstrative_pronouns_list:
        pronouns_type = 'demonstrative_pronouns'
    elif pronouns_list == defining_pronouns_list:
        pronouns_type = 'defining_pronouns'
    elif pronouns_list == relative_pronouns_list:
        pronouns_type = 'relative_pronouns'
    elif pronouns_list == indefinite_pronouns_list:
        pronouns_type = 'indefinite_pronouns'
    elif pronouns_list == negative_pronouns_list:
        pronouns_type = 'negative_pronouns'

    if show_analysis:
        print_pronoun_frequencies(pronouns_type, pronoun_freqs_json, pronoun_counts_json)
        wait_for_enter_to_analyze()

    return pronoun_freqs_json, pronoun_counts_json


def print_pronoun_frequencies(pronouns_type, pronoun_freqs_json, pronoun_counts_json):
    """
    Печатает абсолютные и нормализованные частоты местоимений .

    :param pronoun_freqs_json: JSON-строка с нормализованными частотами местоимений.
    :param pronoun_counts_json: JSON-строка с абсолютными частотами местоимений.
    """
    frequencies = json.loads(pronoun_freqs_json)
    counts = json.loads(pronoun_counts_json)
    pro_name = ''
    if pronouns_type == 'pers_possessive':
        pro_name = 'ЛИЧНЫХ И ПРИТЯЖАТЕЛЬНЫХ'
    elif pronouns_type == 'reflexive_pronoun':
        pro_name = 'ВОЗВРАТНЫХ'
    elif pronouns_type == 'demonstrative_pronouns':
        pro_name = 'УКАЗАТЕЛЬНЫХ'
    elif pronouns_type == 'defining_pronouns':
        pro_name = 'ОПРЕДЕЛИТЕЛЬНЫХ'
    elif pronouns_type == 'relative_pronouns':
        pro_name = 'ОТНОСИТЕЛЬНЫХ'
    elif pronouns_type == 'indefinite_pronouns':
        pro_name = 'НЕОПРЕДЕЛЕННЫХ'
    elif pronouns_type == 'negative_pronouns':
        pro_name = 'ОТРИЦАТЕЛЬНЫХ'

    print(Fore.GREEN + Style.BRIGHT + f"\n                  ЧАСТОТЫ {pro_name} МЕСТОИМЕНИЙ" + Fore.RESET)

    table = Table()
    table.add_column("Местоимение\n", justify="center", style="bold", min_width=20)
    table.add_column("Абсолютная частота\n", justify="center", min_width=20)
    table.add_column("Нормализованная частота \n(%)", justify="center", min_width=20)

    for pronoun, frequency in frequencies.items():
        count = counts.get(pronoun, 0)  # Получаем количество для местоимения
        table.add_row(pronoun, str(count), f"{frequency:.3f}%")

    console.print(table)


if __name__ == "__main__":
    # Текст для примера (сгенерирован ИИ)
    text = """
    Патофизиологические механизмы сердечной недостаточности не ограничиваются только недостаточностью насосной функции сердца — имеют значение также выраженные нарушения состояния мышечно-скелетной, нейроэндокринной, иммунной систем и почек. Ключевым аспектом хронической сердечной недостаточности (ХСН) является эндотелиальная дисфункция, которая влияет на выраженность клинических симптомов у больных и таким образом отражается на качестве жизни пациентов. Провоспалительные цитокины участвуют в развитии эндотелиальной дисфункции, влияют на прогрессирование заболевания и истощение мышечной массы. Наиболее значимым цитокином в этом аспекте является фактор некроза опухоли (ФНО)-α. Однако попытки клинического применения специфических антител для блокирования избыточной продукции ФНО-α при ХСН были в значительной мере безуспешными. Одна из существующих гипотез рассматривает активацию провоспалительных цитокинов как следствие изменения морфологии стенки кишечника и его барьерной функции. Таким образом, липополисахариды (ЛПС) — эндотоксины, которые являются компонентом клеточной стенки грамотрицательных бактерий, — могут попадать в кровоток через отечную стенку кишечника в периоды декомпенсации сердечной недостаточности либо просто вследствие нарушения морфологии кишки. Ингибирование ЛПС может быть клинически более значимым, чем терапия, направленная на отдельные цитокины, образующиеся при воздействии ЛПС. Интерес в этом отношении вызывает урсодеоксихолевая кислота (УДХК) — желчная кислота, использующаяся при лечении больных холестатическими заболеваниями печени и, по-видимому, способная образовывать смешанные мицеллы вокруг ЛПС, приводя к их детоксикации. УДХК является физиологическим компонентом человеческой желчи, которая использовалась при холестатических заболеваниях печени, таких как первичный билиарный цирроз. Этот лекарственный препарат продается с 1950-х гг. в Японии и с середины 1980-х гг. в западных странах. Его структура была впервые описана Iwasaki в 1936 г. В 1970-х гг. стало очевидным, что УДХК может растворять камни в желчном пузыре. Мы предположили, что кратковременное применение УДХК у больных ХСН может способствовать улучшению периферического кровотока вследствие снижения уровня провоспалительных цитокинов. Нами проведено рандомизированное плацебо-контролируемое двойное слепое перекрестное исследование применения УДХК у больных стабильной ХСН. В проспективное исследование нами были включены 17 пациентов из Клиники специалистов по сердечной недостаточности Королевской больницы в Бромптоне (Бромптон, Лондон, Великобритания), у которых, в соответствии с современными рекомендациями Европейского общества кардиологов, была диагностирована клинически стабильная ХСН с фракцией выброса левого желудочка <45%. Причинами хронической сердечной недостаточности у больных были ишемическая болезнь сердца или дилатационная кардиомиопатия. Больные со стенокардией напряжения, периферическими отеками или признаками отека легких, клиническими проявлениями инфекции, тяжелыми нейромышечными заболеваниями, ревматоидным артритом, выраженной почечной дисфункцией (креатинин плазмы>250 μмоль/л), раком в исследование не включались. Также были исключены больные моложе 18 лет и пациенты с нестабильной стенокардией, инфарктом миокарда в анамнезе или инсультом, перенесенным в течение последних 3 мес. Исследование имело перекрестный дизайн, было рандомизированным, плацебо-контролируемым и двойным слепым. В течение всего исследования никто из исследователей, участвовавших в клинической или лабораторной оценке больных, не имел информации о распределении больных в группы лечения. Дизайн исследования представлен на рис. 1. После исходной оценки больные были рандомизированы в группы лечения УДХК (500 мг два раза/день) либо применения соответствующего плацебо в течение 4 нед. После этого периода лечения следовал 4-нед период «отмывки», в течение которого больные не получали изучаемый препарат. И, наконец, в течение последующих 4 нед вновь проводили лечение, заменив у каждого из больных ранее применявшийся препарат на препарат сравнения. Оценка всех изучавшихся параметров проводилась исходно перед включением в исследование и после каждого из двух периодов лечения (УДХК и плацебо). Капсулы УДХК и соответствующие им капсулы, содержащие плацебо, были предоставлены производителем (Dr. Falk Pharma GmbH, Фрайбург, Германия) безвозмездно (как неограниченный грант). Производитель не играл никакой роли в разработке или проведении исследования и не принимал участия в анализе данных. Первичной конечной точкой исследования было сравнение пикового постишемического кровотока в верхней конечности после лечения УДХК и плацебо. Вторичные исходы включали сравнительные изменения пикового постишемического кровотока в нижней конечности, функционального класса ХСН по классификации New York Heart Association (NYHA) и результатов теста с 6-минутной ходьбой, а также клеточных маркеров функции иммунной системы, уровней провоспалительных цитокинов в сыворотке и продукции цитокинов, стимулированной ЛПС. Ранее проведенные рандомизированные исследования показали, что доза УДХК от 10 до 15 мг/кг/день безопасна и эффективно снижает частоту отторжения при трансплантации печени. Доза УДХК, использованная в нашем исследовании, была выбрана с учетом опыта этих исследований. Местный комитет по этике одобрил исследование, и все больные дали письменное информированное согласие. Забор цитратной венозной крови производился из локтевой вены рано утром после того, как больной отдыхал в положении лежа на спине в течение 15 мин. Обработка крови завершалась в течение 1 ч, образцы сыворотки немедленно центрифугировали и хранили до окончательного анализа при температуре —80°. Уровни интерлейкина-6, ФНО-α и растворимых рецепторов фактора некроза опухоли-α 1 типа (рРФНО) в сыворотке определяли, используя коммерческие наборы высокочувствительного фермент-связанного иммуносорбентного анализа (Quantikine HS, R&D Systems, Minneapolis, Minnesota); нижними пределами определения были уровни 0,039 пг/мл, 0,106 пг/мл и 7,8 пг/мл, соответственно. Аликвоты по 1 мл цельной крови, разведенной RPMI 1640 1:1 с добавлением 10 ед/мл гепарина, помещались в 1,5 мл пробирки Eppendorf. Эндотоксин, полученный из Escherichia coli, добавлялся для получения разведений 0,1; 1; 10 и 100 нг/мл. Разведение, аликвотирование и добавление стимуляторов проводилось в стерильных условиях. Пробы без добавления стимулятора служили контролем. Образцы цельной крови инкубировали в течение 6 ч во влажной атмосфере (при 37°С; 5% CO2). После инкубации пробы центрифугировали со скоростью 1500 об/мин в течение 5 мин. Супернатанты собирали и хранили до окончательной оценки при температуре —80°C. Жизнеспособность клеток составляла >90% при оценке методом исключения трипанового синего. Концентрация ФНО-α в супернатанте культуры клеток измерялась с применением наборов стандартного фермент-связанного иммуносорбентного анализа (R&D Systems) в соответствии с инструкциями производителя. Нижний предел обнаружения был 15 пг/мл. До анализа все образцы хранились в замороженном при температуре —80°С состоянии. Анализы всех образцов дублировались, и образцы размораживались только один раз непосредственно для анализа. Все желчные кислоты (холиевая кислота, деоксихолиевая кислота, хенодеоксихолиевая кислота, литохолиевая кислота, УДХК) определялись как неконъюгированные кислоты и как конъюгаты с таурином и глицином методом тандемной масс-спектрометрии в соответствии с ранее описанной методикой. Все субфракции желчных кислот (свободные кислоты и их соответствующие конъюгаты) анализировали методом высокоэффективной жидкостной хроматографии с мониторингом множественных реакций в 3 различных множественных реакциях в ходе одного запуска. Высокоэффективная жидкостная хроматография проводилось на обращенно-фазовой (C18) колонке с применением градиента метанол/вода для хроматографического раствора изобарических желчных кислот. Количественная оценка проводилась с использованием дейтерированных внутренних стандартов и корреляции отношений площадей пиков методом линейной регрессии. Кровоток в верхней и нижней конечностях исследовался веноокклюзивной тензометрической плетизмографией и определялся в мл×100 мл-1× мин-1 в соответствии с ранее описанной методикой. Метод включает прикрепление тензорного датчика — тонкой растяжимой эластической трубки, заполненной ртутью, — вокруг всей окружности конечности. Так как все включенные в исследование пациенты были «правшами», все измерения у них выполнялись на самых крупных отделах правой верхней и правой нижней конечностей. Кровоток в покое оценивался после 15 мин отдыха в положении лежа на спине с удобным, слегка приподнятым положением правой ноги. Стимулированный пиковый кровоток при реактивной гиперемии оценивался непосредственно после прекращения 3-минутной тотальной ишемии, которую вызывали внешней компрессией соответствующей конечности надуванием манжетки на 30 мм рт.ст. выше систолического артериального давления. Затем кровоток измеряли с интервалами в 10 сек в течение 2 мин. Скорость кровотока регистрировалась плетизмографом. Самая высокая зарегистрированная скорость расценивалась как пиковая скорость кровотока. Данные представлены в виде «математическая средняя ± стандартное отклонение». Первичные (постишемический пиковый кровоток в верхних конечностях) и вторичные исходы анализировались на наличие эффекта периода или остаточного эффекта в соответствии с рекомендациями Hills и Armitage. Таких эффектов не было обнаружено (за исключением эффекта периода для щелочной фосфатазы [ЩФ]) и поэтому результаты представлены объединенно в следующем порядке: исходные, после активного лечения и после приема плацебо. Простая регрессия, парный и непарный t тест Стьюдента и хи-квадрат тест применялись в соответствии с необходимостью. Для анализа влияния возрастающих доз ЛПС ex vivo (вне организма) был использован дисперсионный анализ повторных измерений. Значение р<0,05 считалось статистически значимым. В исследование были включены 17 пациентов мужского пола с хронической сердечной недостаточностью ІІ и ІІІ функциональных классов NYHA. Исходные демографические характеристики больных представлены в табл. 1. Лекарственные препараты, которые принимали больные, указаны в табл. 2. 8 больных были рандомизированно распределены в группу, где сначала применялась УДХК, и 9 больных — в группу, где сначала применялось плацебо. В соответствии с оценкой по числу возвращенных капсул УДХА, больные соблюдали режим лечения на 100%. Все больные хорошо переносили УДХК; значимых различий между больными в двух группах лечения не наблюдалось, за исключением немного более высокого уровня аспартаттрансаминазы (АСТ) в группе больных, которые сначала принимали УДХК (табл. 1). В течение первых дней один больной из группы плацебо отозвал согласие участвовать в исследовании и был исключен из всех дальнейших анализов. Значимых изменений кровотока «покоя» в руках или ногах после лечения УДХК не выявлено (р=0,7 в обоих случаях), однако лечение УДХК значимо улучшало пиковый постишемический кровоток по сравнению с результатами в фазе применения плацебо: после лечения УДХК пиковый постишемический кровоток в верхней конечности был на 18% больше (р=0,038) и наблюдалась тенденция к увеличению пикового постишемического кровотока в нижней конечности на 17% (р=0,079). Это не было связано с улучшением оценки функционального класса NYHA или результатов теста с 6-минутной ходьбой (табл. 3). В сравнении с плацебо лечение УДХК привело к значимому увеличению уровней тауро-УДХК и глико-УДХК в сыворотке (табл. 3). Наблюдалось в среднем 16-кратное увеличение уровня УДХК и 67-кратное увеличение уровней суммарно всех субфракций УДХК в сыворотке. Подробнее данные об изменениях уровня других желчных кислот приведены в Онлайн-таблице. Корреляций между кровотоком в верхней конечности и общим уровнем УДХК или любой из субфракций УДХК не выявлено (p>0,05 для всех сравнений). При сравнении результатов, полученных после лечения УДХК, с результатами после применения плацебо было обнаружено значимое снижение сывороточного уровня γ-глютамилтрансферазы (ГГТ) и АСТ (табл. 3). Также наблюдалось значимое снижение уровня ЩФ сыворотки (табл. 3). Однако при этом выявлен значимый эффект периода для ЩФ (р=0,02). Изменений сывороточных концентраций натрия, калия, креатинина, мочевой кислоты, общего белка, альбумина, С-реактивного белка, билирубина, липопротеинов высокой плотности, липопротеинов низкой плотности и общего холестерина не было (р>0,05 для всех показателей). После лечения УДХК мы выявили значимую корреляцию между уровнем УДХК и АСТ (r2=0,48; р=0,005) или общего билирубина (r2=0,29; р=0,03). Достоверных связей между уровнем общей УДХК и ЩФ, ГГТ или С-реактивного белка не было (р>0,05 для всех показателей). Кроме того, после лечения УДХК мы обнаружили значительное снижение рРФНО-1 в сыворотке крови по сравнению с плацебо (табл. 3). Таких изменений уровней интерлейкина-6 или ФНО-α не отмечено (табл. 3). Образцы цельной крови больных ХСН выделяли возрастающие количества ФНО-α при стимуляции ЛПС в возрастающих дозах (данные не представлены). Это было закономерно как для крови, взятой до лечения, так и после лечения УДХК или плацебо. При сравнении результатов оценки после лечения УДХК и плацебо никакого различия количеств ФНО-α, В сравнении с плацебо лечение УДХК привело к значимому увеличению уровней тауро-УДХК и глико-УДХК в сыворотке (табл. 3). Наблюдалось в среднем 16-кратное увеличение уровня УДХК и 67-кратное увеличение уровней суммарно всех субфракций УДХК в сыворотке. Подробнее данные об изменениях уровня других желчных кислот приведены в Онлайн-таблице. Корреляций между кровотоком в верхней конечности и общим уровнем УДХК или любой из субфракций УДХК не выявлено (p>0,05 для всех сравнений). При сравнении результатов, полученных после лечения УДХК, с результатами после применения плацебо было обнаружено значимое снижение сывороточного уровня γ-глютамилтрансферазы (ГГТ) и АСТ (табл. 3). Также наблюдалось значимое снижение уровня ЩФ сыворотки (табл. 3). Однако при этом выявлен значимый эффект периода для ЩФ (р=0,02). Изменений сывороточных концентраций натрия, калия, креатинина, мочевой кислоты, общего белка, альбумина, С-реактивного белка, билирубина, липопротеинов высокой плотности, липопротеинов низкой плотности и общего холестерина не было (р>0,05 для всех показателей). После лечения УДХК мы выявили значимую корреляцию между уровнем УДХК и АСТ (r2=0,48; р=0,005) или общего билирубина (r2=0,29; р=0,03). Достоверных связей между уровнем общей УДХК и ЩФ, ГГТ или С-реактивного белка не было (р>0,05 для всех показателей). Кроме того, после лечения УДХК мы обнаружили значительное снижение рРФНО-1 в сыворотке крови по сравнению с плацебо (табл. 3). Таких изменений уровней интерлейкина-6 или ФНО-α не отмечено (табл. 3). Образцы цельной крови больных ХСН выделяли возрастающие количества ФНО-α при стимуляции ЛПС в возрастающих дозах (данные не представлены). Это было закономерно как для крови, взятой до лечения, так и после лечения УДХК или плацебо. При сравнении результатов оценки после лечения УДХК и плацебо никакого различия количеств ФНО-α, образующихся после стимуляции ЛПС в любых дозах, не наблюдалось (р=0,3 для всех анализов). Абсолютное количество лейкоцитов, нейтрофилов и лимфоцитов было значительно ниже после лечения УДХК, чем после лечения плацебо (табл. 3). После лечения УДХК число нейтрофилов было ниже, чем после применения плацебо (табл. 3). Кроме того, после лечения УДХК количество лимфоцитов был ниже, чем после применения плацебо (табл. 3). Таких различий не было отмечено для моноцитов, эозинофилов или базофилов (р=0,15 для всех показателей). Различий концентрации гемоглобина при сравнении показателей после лечения УДХК и применения плацебо не обнаружено (табл. 3). Кроме того, мы обнаружили значимые связи между уровнем общей УДХК и абсолютным числом лейкоцитов крови (r2=0,34; р=0,02) или абсолютным числом лимфоцитов (r2=0,29; р=0,03) после лечения УДХК. Мы показали, что лечение УДХК в дозе 500 мг два раза/день в течение 4 нед значительно увеличивает постишемический кровоток в верхней конечности. Кроме того, наблюдалась тенденция увеличения постишемического кровотока в ногах. Эти изменения были связаны со значительно более низкими сывороточными уровнями рРФНО-1 и значимым снижением абсолютного числа нейтрофилов и лимфоцитов после лечения УДХК по сравнению с плацебо. Кроме того, мы отметили снижение ГГТ и АСТ сыворотки крови. Однако эти изменения не нашли отражения в улучшении результатов теста с 6-минутной ходьбой или снижении функционального класса NYHA в нашем небольшом исследовании. Не было отмечено изменений секреции ФНО-α стимулированной ЛПС в периферической крови в опытах ex vivo. Лечение УДХК в дозе, использованной в этом исследовании, хорошо переносилось пациентами с ХСН, у которых этот препарат ранее не применяли. Для оценки соблюдения режима лечения УДХК пациентом может быть полезной оценка измерения уровней желчных кислот в сыворотке. На протяжении многих лет снижение периферического кровотока признается одним из основных факторов, ограничивающих толерантность к физической нагрузке у больных ХСН. Хотя ингибиторы ангиотензин-превращающего фермента и блокаторы рецепторов ангиотензина, как известно, улучшают функцию эндотелия при сердечно-сосудистых заболеваниях и сердечной недостаточности, ограничение физических нагрузок остается серьезной проблемой, особенно у пациентов с ХСН. Желчные кислоты, как известно, имеют сосудорасширяющие свойства, и вывод о том, что УДХК оказывает благотворное воздействие на периферическое кровообращение, заслуживает внимания. Степень улучшения периферического кровотока, наблюдавшаяся в нашем исследовании, аналогична наблюдающейся при диуретической терапии декомпенсированной сердечной недостаточности или при лечении другими препаратами, такими как аллопуринол. Более ранние исследования показали, что функция печени может иметь значение при ХСН, в двух исследованиях было показано, что билирубин является сильным прогностическим маркером у пациентов с сердечной недостаточностью. Дефицит оксида азота связан с эндотелиальной дисфункцией, а ФНО-α и другие провоспалительные цитокины имеют отношение к её развитию. Наше исследование не было предназначено для определения механизмов, лежащих в основе действия УДХК, однако прямая индукция оксида азота УДХК не представляется вероятной. Это согласуется с результатами ранее проведенного исследования, в котором лечение УДХК в течение 6 нед 11 пациентов с ишемической болезнью сердца привело к значительному улучшению независимой от оксида азота эндотелиальной вазодилатации, оцененной тензометрической плетизмографией на предплечье. В этом исследовании больным вводили ацетилхолин и нитропруссид, чтобы оценить, соответственно, эндотелий-зависимую и эндотелий-независимую вазодилатацию, и авторы предположили, что в основе полученных ими результатов могут лежать противовоспалительные свойства УДХК. Действительно, препятствие образованию ФНО-α или его растворимых рецепторов представляется возможным эффектом УДХК. Мы обнаружили значительно более низкие уровни рРФНО-1 после лечения УДХК, чем после применения плацебо. Хотя мы не можем исключить возможность случайной находки, считается, что уровень рРФНО-1 лучше отражает долгосрочное воздействие на ФНО-α, чем непосредственно уровень ФНО-α. Одним из свойств УДХК является то, что она, как и холестерин, поддерживает стабильность мембран и предотвращает повреждение мембран, вызванное механическими и химическими воздействиями. Желчные соли присутствуют в желчи в виде смешанных мицелл, которые действуют как растворители и эмульгаторы холестерина, билирубина, лецитина, жирорастворимых витаминов, а также ЛПС. УДХК присутствует в желчи человека в малых количествах, составляя около 3% желчи человека. УДХК обладает мембраностабилизирующим и антиапоптотическим действием. Возможно, что помимо воздействия на провоспалительные медиаторы эти косвенные эффекты также участвуют в улучшении кровотока, выявленном в нашем исследовании, хотя мы не смогли обнаружить прямой связи улучшения кровотока с уровнями общих УДХК-т или субфракций УДХК в сыворотке. Bahrle и соавт. сообщали, что УДХК может иметь благоприятный эффект после трансплантации сердца. В своем исследовании они сравнили частоту острых эпизодов отторжения трансплантата сердца у 21 пациента, получавшего УДХК (500 мг дважды/день в течение >8 нед) в связи с циклоспорин-индуцированным холестазом, и у 31 больных, которые не получали УДХК после пересадки сердца. Они обнаружили, что в первые 6 мес после трансплантации в группе больных, получавших УДХК, количество острых эпизодов отторжения было значительно ниже по сравнению с контрольной группой (р=0,005). Это может быть связано с иммуномодулирующими свойствами УДХК, которые включают в себя не только подавление продукции таких цитокинов, как ФНО-α и γ-интерферон, но и модуляцию функции Т-клеток и B-клеток. Это согласуется с выявленным нами снижением количества лейкоцитов при лечении УДХК по сравнению с плацебо. Превосходное исследование Aouad и соавт. показало, что перевязка общего желчного протока у крыс линии Lewis привела к значительному повышению уровня ЛПС в крови по сравнению с уровнем у контрольных животных. Это открытие позволило предположить, что желчные кислоты способны удерживать бактериальные компоненты в кишечнике. Действительно, применение хенодеоксихолиевой кислоты у крыс в этом исследовании было также связано со значительным уменьшением уровня ЛПС в плазме крови. Поскольку повышенный уровень ЛПС отмечается у больных ХСН, улучшение постишемического кровотока, наблюдавшееся в нашем исследовании, могло быть связано с образованием вокруг ЛПС смешанных мицелл, содержащих УДХК. Следовательно, меньше провоспалительных медиаторов поступало в кровоток, что приводило к улучшению независимой от оксида азота функции эндотелия. Тем не менее, так как лечение УДХК влияло не на все измерявшиеся в нашем исследовании провоспалительные медиаторы, маловероятно, что этот механизм является единственным, определяющим полезные эффекты при лечении УДХК. Несомненно, альтернативные механизмы могут иметь даже более сильное влияние на клинический эффект УДХК, наблюдавшийся в нашем исследовании, поэтому оправданно дальнейшее изучение роли ЛПС при сердечной недостаточности. Тот факт, что лечение УДХК в нашем исследовании было связано со значительным снижением в сыворотке крови АСТ и ГГТ, свидетельствует, что использовалась эффективная доза УДХК. Тем не менее, возможно, что применявшаяся нами доза УДХК была слишком мала, чтобы улучшение функции эндотелия реализовалось в улучшении клинических показателей, в частности результатов теста с 6-минутной ходьбой. Например, доза УДХК, применяющаяся у пациентов с первичным билиарным циррозом, как правило, составляет 10-16 мг/кг массы тела в день. Другая возможность состоит в том, что продолжительность лечения в нашем исследовании была слишком короткой для достижения клинического улучшения (например, усиления функции скелетных мышц). Число больных в нашем исследовании было небольшим, и проведение многочисленных статистических сравнений повышало вероятность случайных результатов. Хотя использование перекрестного дизайна усиливало статистическую мощность исследования, добавление второй базовой оценки изучавшихся показателей перед началом второго периода лечения, вероятно, обеспечило бы дополнительную информацию, особенно важную в связи с тем, что некоторые наши выводы были в большей мере обусловлены изменениями, выявленными в группе плацебо по сравнению с базовыми показателями, а не изменениями в группе УДХК как таковой. УДХК применяли в течение сравнительно короткого времени, и не ясно, будет ли более длительный период времени лечения усиливать эффект УДХК. Хотя УДХК хорошо переносилась больными в нашем исследовании, следует отметить, что к редким, но типичным побочным эффектам УДХК относятся запоры, тошнота и расстройство желудка. Хотя можно рассуждать об использовании нами оптимальных доз УДХК у больных ХСН, тот факт, что при лечении УДХК снизились сывороточные уровни ГГТ и АСТ, указывает, что нами были использованы патофизиологически соответствующие дозы.
    """
    frequencies_json, a = compute_pronoun_frequencies(text, negative_pronouns_list)
